/* ===== inline script ===== */
try {
( () => {
					const lazyloadRunObserver = () => {
						const lazyloadBackgrounds = document.querySelectorAll( `.e-con.e-parent:not(.e-lazyloaded)` );
						const lazyloadBackgroundObserver = new IntersectionObserver( ( entries ) => {
							entries.forEach( ( entry ) => {
								if ( entry.isIntersecting ) {
									let lazyloadBackground = entry.target;
									if( lazyloadBackground ) {
										lazyloadBackground.classList.add( 'e-lazyloaded' );
									}
									lazyloadBackgroundObserver.unobserve( entry.target );
								}
							});
						}, { rootMargin: '200px 0px 200px 0px' } );
						lazyloadBackgrounds.forEach( ( lazyloadBackground ) => {
							lazyloadBackgroundObserver.observe( lazyloadBackground );
						} );
					};
					const events = [
						'DOMContentLoaded',
						'elementor/lazyload/observe',
					];
					events.forEach( ( event ) => {
						document.addEventListener( event, lazyloadRunObserver );
					} );
				} )();
} catch (e) {
    console.warn("Module error in [inline script]:", e);
}
;
/* ===== custom script ===== */
try {
jQuery(document).ready(function($) {
    // 1. Accordion default state reset
    setTimeout(function() {
        $('.elementor-tab-title').removeClass('elementor-active');
        $('.elementor-tab-content').css('display', 'none');
    }, 100);

    // 2. Trigger Elementor animations & reveal hidden elements on scroll / load
    function revealElementorElements() {
        $('.elementor-invisible').each(function() {
            var $el = $(this);
            var rect = this.getBoundingClientRect();
            var windowHeight = window.innerHeight || document.documentElement.clientHeight;
            // Reveal if near viewport or already scrolled past
            if (rect.top <= windowHeight + 100) {
                var settings = $el.data('settings');
                var animation = (settings && settings.animation) || $el.data('animation') || 'fadeIn';
                $el.removeClass('elementor-invisible').addClass('animated ' + animation);
            }
        });
    }

    // Run immediately and on scroll/resize
    revealElementorElements();
    $(window).on('scroll resize', revealElementorElements);

    // Safety fallback: after 800ms, reveal any remaining elementor-invisible elements
    // so no text or headings are ever hidden from the user!
    setTimeout(function() {
        $('.elementor-invisible').each(function() {
            var $el = $(this);
            var settings = $el.data('settings');
            var animation = (settings && settings.animation) || $el.data('animation') || 'fadeIn';
            $el.removeClass('elementor-invisible').addClass('animated ' + animation);
        });
    }, 800);

    // 3. Smooth scroll for anchor links and "Back to top" buttons
    $(document).on('click', 'a[href^="#"]', function(e) {
        var href = $(this).attr('href');
        if (!href || href === '#' || href === '#!') return;
        
        var targetId = href.replace(/^#/, '');
        var targetEl = document.getElementById(targetId);
        
        if (targetEl) {
            e.preventDefault();
            var headerHeight = 120;
            var $deskHeader = $('#qodef-page-header');
            var $mobHeader = $('#qodef-page-mobile-header');
            if ($mobHeader.is(':visible')) {
                headerHeight = $mobHeader.outerHeight() || 70;
            } else if ($deskHeader.is(':visible')) {
                headerHeight = $deskHeader.outerHeight() || 120;
            }
            
            var targetOffset = $(targetEl).offset().top - headerHeight + 5;
            if (targetOffset < 0) targetOffset = 0;

            // Auto-close mobile menu if open
            var $mobNav = $('.qodef-mobile-header-navigation');
            var $mobOpener = $('.qodef-mobile-header-opener');
            if ($mobNav.is(':visible')) {
                $mobNav.slideUp(450);
                $mobOpener.removeClass('qodef--opened');
            }

            $('html, body').stop().animate({
                scrollTop: targetOffset
            }, 800, function() {
                if (history.pushState) {
                    history.pushState(null, null, href);
                } else {
                    window.location.hash = href;
                }
            });
        }
    });

    // Handle Home click in mobile menu
    $(document).on('click', '.qodef-mobile-header-navigation a[href="#"]', function(e) {
        e.preventDefault();
        var $mobNav = $('.qodef-mobile-header-navigation');
        var $mobOpener = $('.qodef-mobile-header-opener');
        if ($mobNav.is(':visible')) {
            $mobNav.slideUp(450);
            $mobOpener.removeClass('qodef--opened');
        }
        $('html, body').stop().animate({
            scrollTop: 0
        }, 800);
    });
});
} catch (e) {
    console.warn("Module error in [custom script]:", e);
}